3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"log/slog"
9		"os"
10		"os/exec"
11		"strings"
12		"sync"
13		"time"
14	
15		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
16		"github.com/entireio/cli/cmd/entire/cli/logging"
17		"github.com/entireio/cli/cmd/entire/cli/settings"
18	
19		"github.com/go-git/go-git/v6"
20		"github.com/go-git/go-git/v6/plumbing"
21		"github.com/go-git/go-git/v6/plumbing/object"
22	)
23	
24	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
25	// The target can be a remote name (e.g., "origin") or a URL for direct push.
26	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
27	// no remote tracking refs — git itself handles the no-op case.
28	// Does not check any settings — callers are responsible for gating.
29	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
30		repo, err := OpenRepository(ctx)
31		if err != nil {
32			return nil //nolint:nilerr // Hook must be silent on failure
33		}
34	
35		// Check if branch exists locally
36		branchRef := plumbing.NewBranchReferenceName(branchName)
37		localRef, err := repo.Reference(branchRef, true)
38		if err != nil {
39			// No branch, nothing to push
40			return nil //nolint:nilerr // Expected when no sessions exist yet
41		}
42	
43		// Only check remote tracking refs when target is a remote name (not a URL).
44		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
45		if !remote.IsURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
46			return nil
47		}
48	
49		return doPushBranch(ctx, target, branchName)
50	}
51	
52	// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
53	// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
54	func hasUnpushedSessionsCommon(repo *git.Repository, remoteName string, localHash plumbing.Hash, branchName string) bool {
55		// Check for remote tracking ref: refs/remotes/<remoteName>/<branch>
56		remoteRefName := plumbing.NewRemoteReferenceName(remoteName, branchName)
57		remoteRef, err := repo.Reference(remoteRefName, true)
58		if err != nil {
59			// Remote branch doesn't exist yet - we have content to push
60			return true
61		}
62	
63		// If local and remote point to same commit, nothing to sync
64		// This is the only case where we skip - any difference needs handling
65		return localHash != remoteRef.Hash()
66	}
67	
68	func displayPushTarget(target string) string {
69		if remote.IsURL(target) {
70			return "checkpoint remote"
71		}
72		return target
73	}
74	
75	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
76	// The target can be a remote name or a URL.
77	func doPushBranch(ctx context.Context, target, branchName string) error {
78		displayTarget := displayPushTarget(target)
79	
80		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
81		stop := startProgressDots(os.Stderr)
82	
83		// Try pushing first
84		result, err := tryPushSessionsCommon(ctx, target, branchName)
85		if err == nil {
86			finishPush(ctx, stop, result, target)
87			return nil
88		}
89		stop("")
90	
91		// Protected refs cannot be fixed by syncing and retrying.
92		var protectedErr *protectedRefError
93		if errors.As(err, &protectedErr) {
94			printProtectedRefBlock(os.Stderr, branchName, target)
95			return nil
96		}
97	
98		// Push failed - likely non-fast-forward. Try to fetch and rebase.
99		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
100		stop = startProgressDots(os.Stderr)
101	
102		if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
103			stop("")
104			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
105			printCheckpointRemoteHint(target)
106			return nil // Don't fail the main push
107		}
108		stop(" done")
109	
110		// Try pushing again after rebase
111		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
112		stop = startProgressDots(os.Stderr)
113	
114		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
115			stop("")
116			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
117			printCheckpointRemoteHint(target)
118		} else {
119			finishPush(ctx, stop, result, target)
120		}
121	
122		return nil
123	}
124	
125	// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
126	// Only prints when the target is a URL (not the user's default remote).
127	func printCheckpointRemoteHint(target string) {
128		if !remote.IsURL(target) {
129			return
130		}
131		fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
132		fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
133	}
134	
135	// settingsHintOnce ensures the settings commit hint prints at most once per process.
136	var settingsHintOnce sync.Once
137	
138	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
139	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
140	// entire.io discovers the external checkpoint repo by reading the committed project
141	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
142	// (not just in settings.local.json or uncommitted local changes).
143	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
144	// single pre-push invocation.
145	func printSettingsCommitHint(ctx context.Context, target string) {
146		if !remote.IsURL(target) {
147			return
148		}
149		settingsHintOnce.Do(func() {
150			if isCheckpointRemoteCommitted(ctx) {
151				return
152			}
153			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
154		})
155	}
156	
157	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
158	// at HEAD contains a valid checkpoint_remote configuration. This is the true
159	// discoverability check: entire.io reads from committed project settings, not from
160	// local overrides or uncommitted changes.
161	func isCheckpointRemoteCommitted(ctx context.Context) bool {
162		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
163		output, err := cmd.Output()
164		if err != nil {
165			return false // file doesn't exist at HEAD
166		}
167		// Parse the committed content and check for checkpoint_remote
168		committed, err := settings.LoadFromBytes(output)
169		if err != nil {
170			return false
171		}
172		return committed.GetCheckpointRemote() != nil
173	}
174	
175	// pushResult describes what happened during a push attempt.
176	type pushResult struct {
177		// upToDate is true when the remote already had all commits (nothing transferred).
178		upToDate bool
179	}
180	
181	// parsePushResult checks git push --porcelain output for ref status flags.
182	// In porcelain mode, each ref gets a tab-delimited status line:
183	//
184	//	<flag>\t<from>:<to>\t<summary>
185	//
186	// where flag '=' means the ref was already up-to-date. This is locale-independent,
187	// unlike the human-readable "Everything up-to-date" message.
188	func parsePushResult(output string) pushResult {
189		for _, line := range strings.Split(output, "\n") {
190			if strings.HasPrefix(line, "=\t") {
191				return pushResult{upToDate: true}
192			}
193		}
194		return pushResult{upToDate: false}
195	}
196	
197	// finishPush stops the progress dots and prints "already up-to-date" or "done"
198	// depending on the push result. Only prints the settings commit hint when new
199	// content was actually pushed.
200	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
201		if result.upToDate {
202			stop(" already up-to-date")
203		} else {
204			stop(" done")
205			printSettingsCommitHint(ctx, target)
206		}
207	}
208	
209	// tryPushSessionsCommon attempts to push the sessions branch.
210	func tryPushSessionsCommon(ctx context.Context, remoteName, branchName string) (pushResult, error) {
211		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
212		defer cancel()
213	
214		result, err := remote.Push(ctx, remoteName, branchName)
215		outputStr := result.Output
216		if err != nil {
217			return pushResult{}, classifyPushFailure(ctx, outputStr, err)
218		}
219	
220		return parsePushResult(outputStr), nil
221	}
222	
223	// protectedRefError means the remote is blocking writes to the ref itself.
224	type protectedRefError struct {
225		output string
226	}
227	
228	func (e *protectedRefError) Error() string {
229		return "remote rejected push to protected ref"
230	}
231	
232	// isProtectedRefRejection detects GitHub ruleset and branch-protection failures.
233	func isProtectedRefRejection(output string) bool {
234		return strings.Contains(output, "GH013") ||
235			strings.Contains(output, "Cannot update this protected ref") ||
236			strings.Contains(output, "protected branch hook declined")
237	}
238	
239	var errNonFastForward = errors.New("non-fast-forward")
240	
241	func isNonFastForwardRejection(output string) bool {
242		if strings.Contains(output, "non-fast-forward") {
243			return true
244		}
245		for _, line := range strings.Split(output, "\n") {
246			if strings.Contains(line, "[rejected]") && strings.Contains(line, "(fetch first)") {
247				return true
248			}
249		}
250		return strings.Contains(output, "Updates were rejected because the tip of your current branch is behind") ||
251			strings.Contains(output, "Updates were rejected because the remote contains work that you do not have locally")
252	}
253	
254	// classifyPushOutput maps failing push stderr to a typed error.
255	func classifyPushOutput(output string) error {
256		if isProtectedRefRejection(output) {
257			return &protectedRefError{output: output}
258		}
259		if isNonFastForwardRejection(output) {
260			return errNonFastForward
261		}
262		if strings.TrimSpace(output) == "" {
263			return errors.New("push failed")
264		}
265		return fmt.Errorf("push failed: %s", output)
266	}
267	
268	func classifyPushFailure(ctx context.Context, output string, pushErr error) error {
269		if strings.TrimSpace(output) != "" {
270			if pushErr != nil {
271				logging.Debug(ctx, "git push failed",
272					slog.String("error", pushErr.Error()),
273					slog.String("output", output),
274				)
275			}
276			return classifyPushOutput(output)
277		}
278		if pushErr != nil {
279			logging.Debug(ctx, "git push failed without output",
280				slog.String("error", pushErr.Error()),
281			)
282			return fmt.Errorf("push failed: %w", pushErr)
283		}
284		return errors.New("push failed")
285	}
286	
287	// printProtectedRefBlock explains that checkpoint syncing was blocked remotely.
288	func printProtectedRefBlock(w io.Writer, ref, target string) {
289		const banner = "[entire] ============================================================"
290		displayTarget := displayPushTarget(target)
291		fmt.Fprintln(w, banner)
292		fmt.Fprintf(w, "[entire] BLOCKED: remote rejected push to %s\n", ref)
293		fmt.Fprintln(w, "[entire] Reason:  GitHub branch protection or repository ruleset (e.g. GH013)")
294		fmt.Fprintf(w, "[entire] Target:  %s\n", displayTarget)
295		fmt.Fprintln(w, "[entire] Impact:  checkpoints are saved locally but NOT synced to this remote.")
296		fmt.Fprintln(w, "[entire] Action:  allow pushes to `entire/*` in your ruleset, or set")
297		fmt.Fprintln(w, "[entire]          `checkpoint_remote` in .entire/settings.json to a separate repo.")
298		fmt.Fprintln(w, banner)
299	}
300	
301	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
302	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
303	// always apply cleanly.
304	// The target can be a remote name or a URL.
305	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
306		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
307		defer cancel()
308	
309		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
310		if err != nil {
311			return fmt.Errorf("resolve fetch target: %w", err)
312		}
313	
314		// Determine fetch refspec. When the resolved fetch target is a URL, use a
315		// temp ref; when it's still a remote name, use the standard remote-tracking
316		// ref.
317		var fetchedRefName plumbing.ReferenceName
318		var refSpec string
319		usedTempRef := remote.IsURL(fetchTarget)
320		if usedTempRef {
321			tmpRef := "refs/entire-fetch-tmp/" + branchName
322			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
323			fetchedRefName = plumbing.ReferenceName(tmpRef)
324		} else {
325			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
326			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
327		}
328	
329		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
330		// Do NOT --unshallow here: on a shallow repo with deep history (e.g. a
331		// shared monorepo), --unshallow downloads the whole repository because
332		// git treats shallow as a global property of the clone, not per-ref.
333		// The downstream reconcile/rebase paths walk only commits visible past
334		// .git/shallow (collectCommitChain / collectCommitsSince), so the
335		// missing pre-shallow history isn't needed to produce a correct rebase.
336		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
337			Remote:   fetchTarget,
338			RefSpecs: []string{refSpec},
339			NoTags:   true,
340		}); fetchErr != nil {
341			return fmt.Errorf("fetch failed: %s", output)
342		}
343	
344		repo, err := OpenRepository(ctx)
345		if err != nil {
346			return fmt.Errorf("failed to open git repository: %w", err)
347		}
348	
349		// Reconcile disconnected metadata branches before rebasing.
350		// The fetch above updated the remote-tracking ref, so reconciliation
351		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
352		// this cherry-picks local commits onto remote tip, updating the local ref.
353		// If reconciliation fails, abort — proceeding to rebase on disconnected
354		// branches would silently combine unrelated histories.
355		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
356			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
357		}
358	
359		// Get local branch (re-read after potential reconciliation update)
360		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
361		if err != nil {
362			return fmt.Errorf("failed to get local ref: %w", err)
363		}
364	
365		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
366		remoteRef, err := repo.Reference(fetchedRefName, true)
367		if err != nil {
368			return fmt.Errorf("failed to get remote ref: %w", err)
369		}
370	
371		// If local is already at or behind remote, fast-forward
372		if localRef.Hash() == remoteRef.Hash() {
373			return nil
374		}
375	
376		// Find merge base
377		repoPath, err := getRepoPath(repo)
378		if err != nil {
379			return fmt.Errorf("failed to get repo path: %w", err)
380		}
381		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
382		if err != nil {
383			return fmt.Errorf("failed to find merge base: %w", err)
384		}
385	
386		// If local is ancestor of remote (merge base == local), fast-forward to remote
387		if mergeBase == localRef.Hash() {
388			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
389			if err := repo.Storer.SetReference(ref); err != nil {
390				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
391			}
392			if usedTempRef {
393				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
394			}
395			return nil
396		}
397	
398		// Collect commits reachable from local but not from remote and cherry-pick
399		// them onto the remote tip. This preserves local-only commits even when the
400		// local metadata branch already contains old merge commits, while avoiding
401		// replaying shared ancestors older than the true merge-base.
402		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
403		if err != nil {
404			return fmt.Errorf("failed to collect local commits: %w", err)
405		}
406	
407		if len(localCommits) == 0 {
408			// No local-only commits — just point to remote
409			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
410			if err := repo.Storer.SetReference(ref); err != nil {
411				return fmt.Errorf("failed to update branch ref: %w", err)
412			}
413			if usedTempRef {
414				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
415			}
416			return nil
417		}
418	
419		shallow, err := loadShallowHashes(ctx, repoPath)
420		if err != nil {
421			return fmt.Errorf("failed to load shallow boundaries: %w", err)
422		}
423	
424		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits, shallow)
425		if err != nil {
426			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
427		}
428	
429		// Update branch ref
430		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
431		if err := repo.Storer.SetReference(newRef); err != nil {
432			return fmt.Errorf("failed to update branch ref: %w", err)
433		}
434	
435		// Clean up temp ref if we used one (best-effort, not critical if it fails)
436		if usedTempRef {
437			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
438		}
439	
440		return nil
441	}
442	
443	// getMergeBase returns the merge base hash of two commits, or an error if they
444	// have no common ancestor.
445	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
446		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
447		defer cancel()
448	
449		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
450		cmd.Dir = repoPath
451		output, err := cmd.Output()
452		if err != nil {
453			var exitErr *exec.ExitError
454			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
455				return plumbing.ZeroHash, errNoMergeBase
456			}
457			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
458		}
459	
460		mergeBase := strings.TrimSpace(string(output))
461		if mergeBase == "" {
462			return plumbing.ZeroHash, errNoMergeBase
463		}
464		return plumbing.NewHash(mergeBase), nil
465	}
466	
467	// collectCommitsSince returns non-merge commits reachable from tip but not from
468	// exclude, ordered oldest-first in topological order.
469	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
470		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
471		defer cancel()
472	
473		// cherryPickOnto computes each commit's delta against its first parent, so
474		// replaying merge commits would incorrectly re-apply changes that arrived via
475		// non-first-parent history. Limit the replay set to non-merge commits.
476		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
477		cmd.Dir = repoPath
478		output, err := cmd.Output()
479		if err != nil {
480			return nil, fmt.Errorf("git rev-list failed: %w", err)
481		}
482	
483		lines := strings.Fields(string(output))
484		if len(lines) > MaxCommitTraversalDepth {
485			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
486		}
487	
488		commits := make([]*object.Commit, 0, len(lines))
489		for _, line := range lines {
490			hash := plumbing.NewHash(line)
491			commit, commitErr := repo.CommitObject(hash)
492			if commitErr != nil {
493				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
494			}
495			if len(commit.ParentHashes) > 1 {
496				continue
497			}
498			commits = append(commits, commit)
499		}
500	
501		return commits, nil
502	}
503	
504	// startProgressDots prints dots to w every second until the returned stop function
505	// is called. The stop function prints the given suffix and a newline.
506	func startProgressDots(w io.Writer) func(suffix string) {
507		done := make(chan struct{})
508		stopped := make(chan struct{})
509		go func() {
510			defer close(stopped)
511			ticker := time.NewTicker(time.Second)
512			defer ticker.Stop()
513			for {
514				select {
515				case <-done:
516					return
517				case <-ticker.C:
518					fmt.Fprint(w, ".")
519				}
520			}
521		}()
522		return func(suffix string) {
523			close(done)
524			<-stopped // Wait for goroutine to finish before writing suffix
525			fmt.Fprintln(w, suffix)
526		}
527	}
