32	// from the origin remote's protocol/host and the configured checkpoint repo.
33	// Otherwise, the origin remote URL is returned directly.
34	//
35	// If ENTIRE_CHECKPOINT_TOKEN is set and a checkpoint remote is configured, HTTPS is
36	// forced so the token can be used even when origin is configured via SSH.
37	func FetchURL(ctx context.Context, opts ...FetchURLOptions) (string, error) {
38		var opt FetchURLOptions
39		if len(opts) > 0 {
40			opt = opts[0]
41		}
42	
43		getRemoteURL := GetRemoteURL
44		if opt.WorktreeRoot != "" {
45			ctx = settings.WithWorktreeRoot(ctx, opt.WorktreeRoot)
46			getRemoteURL = func(ctx context.Context, remoteName string) (string, error) {
47				return GetRemoteURLInDir(ctx, opt.WorktreeRoot, remoteName)
48			}
49		}
50	
51		withToken := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != ""
52	
53		originURL, originErr := getRemoteURL(ctx, originRemote)
54		if originErr != nil {
55			originURL = ""
56		}
