58		if originURL != "" && withToken {
59			if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
60				originURL = tokenURL
61			}
62		}
63	
64		s, err := settings.Load(ctx)
65		if err != nil {
66			if originURL != "" {
67				logFallback(ctx, "fetch", originURL, "load settings", err)
68				return originURL, nil
69			}
70			return "", fmt.Errorf("load settings: %w", err)
71		}
72	
73		config := s.GetCheckpointRemote()
74		if config == nil {
75			if originURL == "" {
76				return "", fmt.Errorf("no fetch URL found: %w", originErr)
77			}
78			return originURL, nil
79		}
