93			// In token-based execution path, short-circuit to avoid additional
94			// change in protocol.
95			if originURL != "" {
96				return originURL, nil
97			}
98		}
99	
100		if originURL == "" {
101			return "", fmt.Errorf("no fetch URL found: %w", originErr)
102		}
103	
104		info, err := ParseURL(originURL)
105		if err != nil {
106			logFallback(ctx, "fetch", originURL, "parse origin remote URL", err)
107			return originURL, nil
108		}
