119	// PushURL returns the effective checkpoint push URL for the current repository.
120	// Unlike FetchURL:
121	//   - it derives protocol from the requested push remote, not always origin
122	//   - it skips checkpoint remote use when the push remote owner differs
123	//     from the configured checkpoint remote owner
124	//
125	// If ENTIRE_CHECKPOINT_TOKEN is set, HTTPS is forced so the token can be used
126	// even when the push remote is configured via SSH.
127	//
128	// The boolean return value reports whether a dedicated checkpoint_remote is
129	// configured and should be used for push. When false, the returned URL is the
130	// repository's origin URL as a fallback.
131	func PushURL(ctx context.Context, pushRemoteName string) (string, bool, error) {
132		originURL := ""
133		if resolvedOriginURL, err := GetRemoteURL(ctx, originRemote); err == nil {
134			originURL = resolvedOriginURL
135		}
136	
137		s, err := settings.Load(ctx)
138		if err != nil {
139			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
140			if fallbackErr == nil {
141				logFallback(ctx, "push", fallbackURL, "load settings", err,
142					slog.String("push_remote", pushRemoteName),
143				)
144				return fallbackURL, false, nil
145			}
146			return "", false, fmt.Errorf("load settings: %w", err)
147		}
148	
149		config := s.GetCheckpointRemote()
150		if config == nil {
151			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
152			if fallbackErr != nil {
153				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
154			}
155			return fallbackURL, false, nil
156		}
157	
158		pushRemoteURL, err := GetRemoteURL(ctx, pushRemoteName)
159		if err != nil {
160			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
161			if fallbackErr == nil {
162				logFallback(ctx, "push", fallbackURL, "get push remote URL", err,
163					slog.String("push_remote", pushRemoteName),
164				)
165				return fallbackURL, false, nil
166			}
167			return "", true, fmt.Errorf("no push URL found: %w", err)
168		}
169	
170		pushInfo, err := ParseURL(pushRemoteURL)
171		if err != nil {
172			if originURL != "" {
173				logFallback(ctx, "push", originURL, "parse push remote URL", err,
174					slog.String("push_remote", pushRemoteName),
175				)
176				return originURL, false, nil
177			}
178			return "", true, fmt.Errorf("no push URL found: %w", err)
179		}
180		if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
181			// Keep the port only when the source was already HTTPS. SSH ports
182			// (e.g., :2222) don't map to HTTPS ports on the same host.
183			port := ""
184			if pushInfo.Protocol == ProtocolHTTPS {
185				port = pushInfo.Port
186			}
187			pushInfo = &Info{
188				Protocol: ProtocolHTTPS,
189				Host:     pushInfo.Host,
190				Port:     port,
191				Owner:    pushInfo.Owner,
192				Repo:     pushInfo.Repo,
193			}
194		}
195	
196		checkpointOwner := config.Owner()
197		if pushInfo.Owner != "" && checkpointOwner != "" && !strings.EqualFold(pushInfo.Owner, checkpointOwner) {
198			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
199			if fallbackErr != nil {
200				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
201			}
202			return fallbackURL, false, nil
203		}
204	
205		pushURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
206		if err != nil {
207			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
208			if fallbackErr == nil {
