210					slog.String("push_remote", pushRemoteName),
211				)
212				return fallbackURL, false, nil
213			}
214			return "", true, fmt.Errorf("no push URL found: %w", err)
215		}
216	
217		return pushURL, true, nil
218	}
219	
220	// Configured reports whether a structured checkpoint_remote is configured.
221	func Configured(ctx context.Context) bool {
222		s, err := settings.Load(ctx)
223		if err != nil {
224			logging.Warn(ctx, "checkpoint remote configuration unavailable; treating as not configured",
225				slog.String("error", err.Error()),
226			)
227			return false
228		}
229		return s.GetCheckpointRemote() != nil
230	}
