232	// GetRemoteURL returns the URL configured for the named git remote.
233	func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
234		url, err := gitremote.GetRemoteURL(ctx, remoteName)
235		if err != nil {
236			return "", fmt.Errorf("get remote URL: %w", err)
237		}
238		return url, nil
239	}
240	
241	// GetRemoteURLInDir returns the URL configured for the named git remote in dir.
242	func GetRemoteURLInDir(ctx context.Context, dir, remoteName string) (string, error) {
243		url, err := gitremote.GetRemoteURLInDir(ctx, dir, remoteName)
244		if err != nil {
245			return "", fmt.Errorf("get remote URL: %w", err)
246		}
247		return url, nil
248	}
249	
250	// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
251	func ParseURL(rawURL string) (*Info, error) {
252		info, err := gitremote.ParseURL(rawURL)
253		if err != nil {
254			return nil, fmt.Errorf("parse URL: %w", err)
255		}
256		return info, nil
257	}
258	
259	func DeriveCheckpointURL(pushRemoteURL string, config *settings.CheckpointRemoteConfig) (string, error) {
260		info, err := gitremote.ParseURL(pushRemoteURL)
261		if err != nil {
262			return "", fmt.Errorf("cannot parse push remote URL: %w", err)
263		}
264		return deriveCheckpointURLFromInfo(info, config)
265	}
266	
267	// ExtractOwnerFromRemoteURL extracts the owner component from a git remote URL.
268	func ExtractOwnerFromRemoteURL(rawURL string) string {
269		return gitremote.ExtractOwnerFromRemoteURL(rawURL)
270	}
271	
272	func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
273		switch info.Protocol {
274		case ProtocolSSH:
275			// SCP-style (git@host:repo) doesn't support ports. When a non-default
276			// port is set (e.g., from ssh://git@host:2222/...), use the ssh:// URL form.
277			if info.Port != "" {
278				return fmt.Sprintf("ssh://git@%s/%s.git", info.HostPort(), config.Repo), nil
279			}
280			return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
281		case ProtocolHTTPS:
282			return fmt.Sprintf("https://%s/%s.git", info.HostPort(), config.Repo), nil
283		default:
284			return "", fmt.Errorf("unsupported protocol %q in origin remote", info.Protocol)
285		}
286	}
287	
288	func deriveTokenOriginURL(originURL string) (string, bool) {
289		info, err := gitremote.ParseURL(originURL)
290		if err != nil {
291			return "", false
292		}
293		if info.Host == "" || info.Owner == "" || info.Repo == "" {
294			return "", false
295		}
296		// Keep the port only when the source was already HTTPS. SSH ports
297		// (e.g., :2222) don't map to HTTPS ports on the same host.
298		hostPort := info.Host
299		if info.Protocol == ProtocolHTTPS {
300			hostPort = info.HostPort()
301		}
302		return fmt.Sprintf("https://%s/%s/%s.git", hostPort, info.Owner, info.Repo), true
303	}
304	
305	func providerHost(provider string) (string, bool) {
306		switch strings.ToLower(strings.TrimSpace(provider)) {
307		case "github":
308			return "github.com", true
309		case "gitlab":
310			return "gitlab.com", true
311		default:
312			return "", false
313		}
314	}
315	
316	// RedactURL removes credentials and query parameters from a URL for safe logging.
317	func RedactURL(rawURL string) string {
318		return gitremote.RedactURL(rawURL)
319	}
320	
321	func logFallback(ctx context.Context, operation, fallbackURL, reason string, err error, attrs ...any) {
322		logAttrs := []any{
323			slog.String("operation", operation),
324			slog.String("fallback_url", RedactURL(fallbackURL)),
325			slog.String("reason", reason),
326			slog.String("error", err.Error()),
327		}
328		logAttrs = append(logAttrs, attrs...)
329		logging.Warn(ctx, "checkpoint remote URL resolution fell back to alternate remote URL", logAttrs...)
330	}
331	
332	func resolvePushFallbackURL(ctx context.Context, pushRemoteName, originURL string) (string, error) {
333		if originURL != "" {
334			if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
335				if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
336					return tokenURL, nil
337				}
338			}
339			return originURL, nil
340		}
341		if pushRemoteName == "" {
342			return "", fmt.Errorf("no push remote specified and remote %q not found", originRemote)
343		}
344		if pushRemoteName == originRemote {
345			return "", fmt.Errorf("remote %q not found", originRemote)
346		}
347		pushURL, err := GetRemoteURL(ctx, pushRemoteName)
348		if err != nil {
349			return "", err
350		}
351		if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
352			if tokenURL, ok := deriveTokenOriginURL(pushURL); ok {
353				return tokenURL, nil
354			}
355		}
356		return pushURL, nil
357	}
