// git-remote-entire is a Git remote helper that allows using entire:// URLs.
// Usage: git clone entire://host.com/project/repo
//
// Git invokes this binary as: git-remote-entire <remote-name> <url>
// The helper proxies Git smart HTTP protocol to the Entire server with automatic authentication.
//
// Node discovery: the host in the URL is the cluster entry domain (fronted by
// a load balancer). The helper sends info/refs there on a cold start; the
// server either serves the request directly or 307s to a hosting replica, and
// every response carries an X-Entire-Replicas header listing the replica set.
// The helper caches that set at ~/.cache/entire/nodes.json and sends
// subsequent requests (pack data, later info/refs) direct to a cached replica.
package main

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"math/rand/v2"
	"net/http"
	"net/http/httputil"
	"net/url"
	"os"
	"os/signal"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/antithesishq/antithesis-sdk-go/assert"

	"entire.io/client"
	"entire.io/client/clilogin"
	"entire.io/client/contexts"
	"entire.io/client/discovery"
	"entire.io/client/httpclient"
	"entire.io/cmd/git-remote-entire/bundleuri"
)

func main() {
	if len(os.Args) < 3 {
		fatal("usage: git-remote-entire <remote-name> <url>")
	}

	skipTLS := os.Getenv("ENTIRE_TLS_SKIP_VERIFY") == "true"
	rawURL := os.Args[2]

	debugf("invoked: remote=%s url=%s", os.Args[1], rawURL)
	if skipTLS {
		debugf("ENTIRE_TLS_SKIP_VERIFY=true: TLS verification disabled for all HTTP clients")
	}

	// Parse the entire:// URL
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		fatal("invalid URL %q: %v", rawURL, err)
	}

	if parsedURL.Scheme != "entire" {
		fatal("unsupported URL scheme %q (expected 'entire')", parsedURL.Scheme)
	}

	if parsedURL.Host == "" {
		fatal("missing host in URL %q", rawURL)
	}

	// Tie HTTP request lifetimes to the parent git process. Ctrl-C in the
	// shell delivers SIGINT to the whole foreground process group, which
	// includes us; cancelling ctx aborts in-flight info/refs and pack
	// transfers instead of letting them run to the read timeout after the
	// user has given up. Stdin reads (scanner.Scan, io.ReadFull) aren't
	// ctx-aware — they unblock when git closes its stdout, which it does
	// on SIGINT.
	//
	// After the first signal we unhook our handler so a second Ctrl-C hits
	// the Go runtime's default disposition and hard-exits. Without this,
	// signal.NotifyContext silently drops further signals (the buffered
	// channel fills and the goroutine has already returned), leaving the
	// user with no escape hatch if graceful shutdown wedges — e.g. on a
	// stdin read that didn't get EOF because git is slow to close pipes.
	//
	// If we're still alive a couple of seconds after the first signal, surface
	// the escape-hatch hint. Normal-exit case never reaches the print because
	// main has returned and the runtime has torn the goroutine down.
	ctx, stopSignals := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stopSignals()
	go func() {
		<-ctx.Done()
		stopSignals()
		time.Sleep(2 * time.Second)
		fmt.Fprintln(os.Stderr, "git-remote-entire: shutdown taking longer than expected; press Ctrl-C again to force-quit")
	}()

	clusterHost := parsedURL.Host
	debugf("clusterHost=%s repoPath=%s", clusterHost, parsedURL.Path)
	nodeCfg := resolveNodes(parsedURL)
	debugf("entry URL: %s (used when cached replicas are empty/exhausted)", nodeCfg.entryURL)

	var (
		token, coreURL string
		// contextName is the contexts.json entry name that resolved
		// this cluster — empty under the ENTIRE_TOKEN flow. Non-empty
		// enables auto-binding (cluster → context) after the first
		// successful STS exchange.
		contextName string
	)

	// JWT resolution: the proxy exchanges the login JWT for a repo-scoped
	// token before each git op (the server rejects raw login JWTs at /git/).
	//
	// Resolution order:
	//   1. ENTIRE_TOKEN env var (CI / workload identity) — the home
	//      region URL is read from the JWT's aud claim (login and
	//      sa-session JWTs both carry aud=baseURL).
	//   2. contexts.json — the binding (or current_context fallback)
	//      tells us which core, handle, and keychain slot to use.
	if envToken := os.Getenv("ENTIRE_TOKEN"); envToken != "" {
		debugf("login JWT from ENTIRE_TOKEN env override (skipping contexts.json + keyring lookup)")
		token = envToken
		var err error
		coreURL, err = coreURLFromEnvToken(envToken)
		if err != nil {
			fatal("%v", err)
		}
		debugf("STS endpoint from JWT aud claim: %s/api/authz/sts/token", coreURL)
	} else {
		configDir := defaultConfigDir()
		debugf("reading config from %s (contexts.json maps cluster host → context, falling back to current_context)", configDir)

		var (
			keychainService, username string
			err                       error
		)
		coreURL, contextName, keychainService, username, err = resolveContext(ctx, newHTTPClient(skipTLS), configDir, clusterHost, debugf)
		if err != nil {
			fatal("%v", err)
		}
		debugf("resolved context %q for cluster %s: handle=%s keychain=%s", contextName, clusterHost, username, keychainService)
		debugf("loading login JWT from keyring (service=%s user=%s)", keychainService, username)

		token, err = client.GetTokenWithRefresh(ctx, client.AuthRefreshConfig{
			KeyringService: keychainService,
			BaseURL:        nodeCfg.entryURL,
			Username:       username,
			CoreBaseURL:    coreURL,
			HTTPClient:     newHTTPClient(skipTLS),
			ClientID:       clilogin.DefaultClientID,
		})
		if err != nil {
			fatal("authentication failed for %q: %v", rawURL, err)
		}
		debugf("STS endpoint pinned to context core URL: %s/api/authz/sts/token", coreURL)
	}

	// When a cached replica fails, invalidate the repo cache entry so the
	// next invocation falls back to the entry domain cleanly. Within this
	// invocation recovery is automatic: infoRefs re-resolves through the
	// entry domain once the cached set is exhausted.
	var onNodeFailed func(string)
	if nodeCfg.caching() {
		onNodeFailed = func(failedNode string) {
			debugf("cached replica %s failed, invalidating cache for %s", failedNode, nodeCfg.repoPath)
			invalidateCachedReplicas(clusterHost, nodeCfg.repoPath)
		}
	}

	// Auto-bind cluster→context after the first successful STS exchange.
	// Skipped under api-key and ENTIRE_TOKEN flows (no contextName).
	var onScopedSuccess func()
	if contextName != "" {
		boundCfgDir := defaultConfigDir()
		onScopedSuccess = func() {
			if err := contexts.BindCluster(boundCfgDir, clusterHost, contextName); err != nil {
				debugf("BindCluster %s → %s: %v", clusterHost, contextName, err)
			}
		}
	}

	if err := runProtocol(ctx, parsedURL.Path, nodeCfg, token, coreURL, skipTLS, onNodeFailed, onScopedSuccess, os.Stdin, os.Stdout); err != nil {
		fatal("%v", err)
	}
}

// nodeConfig is the discovery-time state the proxy needs: an entry-domain URL
// to use when the cached replica set is empty or exhausted, whatever replicas
// are currently cached, the cluster host for same-cluster redirect checks,
// and the repo path used as the cache key (empty when the URL has no path,
// in which case caching is disabled).
type nodeConfig struct {
	initialNodes []string
	entryURL     string
	clusterHost  string
	repoPath     string
}

